// ============================================================================
// sync-settlement — API-Sports final score ingestion + automated grading (Phase 3)
// ----------------------------------------------------------------------------
// Fetches fixtures via ONE date-only call (GET /fixtures?date=X or /games?date=X —
// no league/season), filters to LEAGUE_CATALOG, settles completed matches, then
// grades linked predictions server-side (with multiplier).
//
// Invoke (POST):
//   { "sport": "football" | "rugby", "date": "YYYY-MM-DD" (optional) }
//
// Required secrets (Deno.env):
//   API_SPORTS_KEY               — API-Sports key (no legacy fallbacks)
//   SUPABASE_URL                 — project URL (auto-injected on deploy)
//   SUPABASE_SERVICE_ROLE_KEY    — service role key (auto-injected on deploy)
// ============================================================================

import { createClient } from "@supabase/supabase-js";
import {
  ApiSportsClient,
  DAILY_BUDGET_CAP,
  UpstreamAuthError,
  getApiSportsKey,
  type Sport as SharedSport,
} from "../_shared/apiSportsClient.ts";
import { FOOTBALL_API_IDS } from "../_shared/footballLeagues.ts";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const FOOTBALL_FINISHED = new Set(["FT", "AET", "PEN", "AWD", "WO"]);
const RUGBY_FINISHED = new Set([
  "FT",
  "FINISHED",
  "ENDED",
  "AET",
  "AWD",
  "WO",
]);

type Sport = "football" | "rugby";

/** ONLY these league IDs are settled (must match sync-schedule catalog). */
const LEAGUE_CATALOG: Record<Sport, ReadonlySet<number>> = {
  football: FOOTBALL_API_IDS,
  rugby: new Set([13, 16, 22, 14, 15, 26, 19, 10]),
};

interface FinalScores {
  home: number;
  away: number;
}

interface SettledMatch {
  id: string;
  external_fixture_id: number | null;
  actual_home_score: number;
  actual_away_score: number;
}

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
  });
}

function todayUtc(): string {
  return new Date().toISOString().slice(0, 10);
}

function isFinished(sport: Sport, item: any): boolean {
  const fixture = item.fixture ?? item;
  const short = String(fixture.status?.short ?? item.status?.short ?? "")
    .toUpperCase();
  const long = String(fixture.status?.long ?? item.status?.long ?? "")
    .toUpperCase();

  if (sport === "football") {
    return FOOTBALL_FINISHED.has(short);
  }

  return RUGBY_FINISHED.has(short) ||
    long === "FINISHED" ||
    long.includes("FINISHED");
}

/**
 * Football final score: prefer post-extra-time, excluding penalty shootout totals.
 * API-Sports exposes score.extratime / score.fulltime separately from penalties.
 */
function extractFootballFinalScores(item: any): FinalScores | null {
  const fixture = item.fixture ?? item;
  const statusShort = String(fixture.status?.short ?? "").toUpperCase();
  const score = item.score ?? fixture.score ?? {};
  const goals = item.goals ?? {};

  // AET/PEN: regulation+ET totals live on score.extratime when present.
  if (statusShort === "PEN" || statusShort === "AET") {
    const extra = score.extratime;
    if (extra?.home != null && extra?.away != null) {
      return { home: Number(extra.home), away: Number(extra.away) };
    }
  }

  // Verified mapping: goals.home / goals.away
  if (goals.home != null && goals.away != null) {
    return { home: Number(goals.home), away: Number(goals.away) };
  }

  const fulltime = score.fulltime;
  if (fulltime?.home != null && fulltime?.away != null) {
    return { home: Number(fulltime.home), away: Number(fulltime.away) };
  }

  return null;
}

function extractRugbyFinalScores(item: any): FinalScores | null {
  const scores = item.scores ?? item.fixture?.scores;
  if (scores?.home != null && scores?.away != null) {
    return { home: Number(scores.home), away: Number(scores.away) };
  }
  return null;
}

function extractFinalScores(sport: Sport, item: any): FinalScores | null {
  return sport === "football"
    ? extractFootballFinalScores(item)
    : extractRugbyFinalScores(item);
}

type PowerUpType =
  | "double_bubble"
  | "safety_net"
  | "sniper"
  | "banker"
  | "pitchside_master";

const EXACT_SCORE_POINTS = 5;
const SAFETY_FLOOR = 5;

/**
 * Football base: Exact 5 · Exact GD 3 · Outcome 1 · Miss 0.
 * Keep in sync with src/services/scoringEngine.ts and SQL pitchside_football_points.
 */
function calculateFootballPoints(
  predictedHome: number,
  predictedAway: number,
  actualHome: number,
  actualAway: number,
): number {
  const predictedWinner = predictedHome > predictedAway
    ? "home"
    : predictedHome < predictedAway
    ? "away"
    : "draw";
  const actualWinner = actualHome > actualAway
    ? "home"
    : actualHome < actualAway
    ? "away"
    : "draw";

  if (predictedWinner !== actualWinner) return 0;
  if (predictedHome === actualHome && predictedAway === actualAway) return 5;

  const predictedMargin = predictedHome - predictedAway;
  const actualMargin = actualHome - actualAway;
  if (predictedMargin === actualMargin) return 3;

  return 1;
}

/** Keep in sync with scoringEngine / pitchside_rugby_points (5 / 3 / 1). */
function calculateRugbyPoints(
  predictedHome: number,
  predictedAway: number,
  actualHome: number,
  actualAway: number,
): number {
  const predictedWinner = predictedHome > predictedAway
    ? "home"
    : predictedHome < predictedAway
    ? "away"
    : "draw";
  const actualWinner = actualHome > actualAway
    ? "home"
    : actualHome < actualAway
    ? "away"
    : "draw";

  if (predictedWinner !== actualWinner) return 0;

  const predictedMargin = Math.abs(predictedHome - predictedAway);
  const actualMargin = Math.abs(actualHome - actualAway);
  const marginDifference = Math.abs(predictedMargin - actualMargin);

  if (marginDifference === 0) return 5;
  if (marginDifference <= 7) return 3;
  if (marginDifference <= 10) return 1;
  return 0;
}

function calculateBasePoints(
  sport: Sport,
  predictedHome: number,
  predictedAway: number,
  actualHome: number,
  actualAway: number,
): number {
  return sport === "football"
    ? calculateFootballPoints(predictedHome, predictedAway, actualHome, actualAway)
    : calculateRugbyPoints(predictedHome, predictedAway, actualHome, actualAway);
}

function applyPowerUp(
  basePoints: number,
  powerup: PowerUpType | null | undefined,
  predictedHome: number,
  predictedAway: number,
  actualHome: number,
  actualAway: number,
): { points: number; isBankerExact: boolean } {
  let points = basePoints;
  let isBankerExact = false;

  const predictedWinner = predictedHome > predictedAway
    ? "home"
    : predictedHome < predictedAway
    ? "away"
    : "draw";
  const actualWinner = actualHome > actualAway
    ? "home"
    : actualHome < actualAway
    ? "away"
    : "draw";
  const outcomeCorrect = predictedWinner === actualWinner;
  const isExact = predictedHome === actualHome && predictedAway === actualAway;

  if (powerup === "banker") {
    if (outcomeCorrect) {
      points = EXACT_SCORE_POINTS;
      isBankerExact = true;
    }
  } else if (powerup === "sniper" && isExact) {
    points = Math.round(points * 1.5);
  }

  if (powerup === "double_bubble") points *= 2;
  else if (powerup === "pitchside_master") points *= 3;

  if (powerup === "safety_net" && points === 0) points = SAFETY_FLOOR;

  return { points, isBankerExact };
}

function applyMultiplier(basePoints: number, multiplier: number | null): number {
  const factor = multiplier != null && multiplier > 0 ? Number(multiplier) : 1;
  return Math.round(basePoints * factor);
}

function normalizeCompletedMatch(sport: Sport, item: any): SettledMatch | null {
  if (!isFinished(sport, item)) return null;

  const fixture = item.fixture ?? item;
  const apiId = fixture.id ?? item.id;
  if (apiId == null) return null;

  const scores = extractFinalScores(sport, item);
  if (!scores) return null;

  return {
    id: `${sport}-${apiId}`,
    external_fixture_id: Number.isFinite(Number(apiId)) ? Number(apiId) : null,
    actual_home_score: scores.home,
    actual_away_score: scores.away,
  };
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: CORS_HEADERS });
  }
  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed. Use POST." }, 405);
  }

  const apiKey = getApiSportsKey();
  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

  if (!apiKey) {
    return jsonResponse({ error: "Missing API_SPORTS_KEY secret." }, 500);
  }
  if (!supabaseUrl || !serviceRoleKey) {
    return jsonResponse(
      { error: "Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY secret." },
      500,
    );
  }

  let payload: { sport?: string; date?: string };
  try {
    payload = await req.json();
  } catch {
    return jsonResponse({ error: "Invalid JSON body." }, 400);
  }

  const sport = payload.sport as Sport;
  if (sport !== "football" && sport !== "rugby") {
    return jsonResponse(
      { error: "`sport` must be 'football' or 'rugby'." },
      400,
    );
  }

  const date = payload.date && /^\d{4}-\d{2}-\d{2}$/.test(payload.date)
    ? payload.date
    : todayUtc();

  const supabase = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false },
  });

  try {
  // Skip API call when nothing in DB could need grading.
  const nowIso = new Date().toISOString();
  const { count: liveCount } = await supabase
    .from("matches")
    .select("id", { count: "exact", head: true })
    .eq("sport", sport)
    .eq("status", "live");
  const { count: overdueCount } = await supabase
    .from("matches")
    .select("id", { count: "exact", head: true })
    .eq("sport", sport)
    .neq("status", "completed")
    .lt("kickoff_time", nowIso);

  if ((liveCount ?? 0) === 0 && (overdueCount ?? 0) === 0) {
    console.log(
      `[sync-settlement] Skipping ${sport} — no pending matches in DB`,
    );
    return jsonResponse({
      sport,
      date,
      skipped: "nothing_pending",
      fetched: 0,
      completed: 0,
      matches_settled: 0,
      predictions_graded: 0,
      budget: DAILY_BUDGET_CAP,
    });
  }

  const client = new ApiSportsClient({
    supabase,
    apiKey,
    caller: "sync-settlement",
    budgetCap: DAILY_BUDGET_CAP,
  });

  const path = sport === "football" ? "/fixtures" : "/games";
  const label = `settlement ${sport} date=${date} (date-only)`;
  // Bare date= — no league/season. Current-season finals inside free date window.
  const result = await client.get(sport as SharedSport, path, { date }, label);

  if (!result.ok) {
    if (result.reason === "budget_exhausted") {
      client.logRunSummary({ sport, date, skipped: "budget_exhausted" });
      return jsonResponse(
        {
          error: "budget_exhausted",
          callsMadeToday: result.callsMadeToday,
          budget: DAILY_BUDGET_CAP,
        },
        429,
      );
    }
    if (result.reason === "validation_error") {
      return jsonResponse(
        { error: "API-Sports validation error.", detail: result.message },
        400,
      );
    }
    return jsonResponse(
      {
        error:
          result.reason === "plan_blocked"
            ? "API-Sports plan blocked."
            : "API-Sports request failed.",
        detail: result.message,
      },
      502,
    );
  }

  const fixtures: any[] = Array.isArray(result.json?.response)
    ? result.json.response
    : [];
  const catalog = LEAGUE_CATALOG[sport];
  const catalogFixtures = fixtures.filter((item) => {
    const leagueId = Number(item?.league?.id ?? item?.league_id);
    return Number.isFinite(leagueId) && catalog.has(leagueId);
  });
  const completed = catalogFixtures
    .map((item) => normalizeCompletedMatch(sport, item))
    .filter((row): row is SettledMatch => row !== null);

  if (completed.length === 0) {
    client.logRunSummary({
      sport,
      date,
      fetched: fixtures.length,
      completed: 0,
    });
    return jsonResponse({
      sport,
      date,
      fetched: fixtures.length,
      completed: 0,
      matches_settled: 0,
      predictions_graded: 0,
      callsThisRun: client.stats.callsThisRun,
      budget: DAILY_BUDGET_CAP,
    });
  }

  let matchesSettled = 0;
  let predictionsGraded = 0;
  const errors: string[] = [];

  for (const match of completed) {
    const { data: existing, error: fetchErr } = await supabase
      .from("matches")
      .select("id, base_multiplier")
      .eq("id", match.id)
      .maybeSingle();

    if (fetchErr) {
      errors.push(`${match.id}: failed to load match — ${fetchErr.message}`);
      continue;
    }
    if (!existing) {
      errors.push(`${match.id}: match not found in database (run sync-schedule first)`);
      continue;
    }

    const { error: matchErr } = await supabase
      .from("matches")
      .update({
        status: "completed",
        external_fixture_id: match.external_fixture_id,
        actual_home_score: match.actual_home_score,
        actual_away_score: match.actual_away_score,
        provisional_home_score: null,
        provisional_away_score: null,
        match_minute: null,
        updated_at: new Date().toISOString(),
      })
      .eq("id", match.id);

    if (matchErr) {
      errors.push(`${match.id}: match update failed — ${matchErr.message}`);
      continue;
    }
    matchesSettled++;

    const { data: predictions, error: predFetchErr } = await supabase
      .from("predictions")
      .select(
        "id, user_id, predicted_home_score, predicted_away_score, applied_powerup_id",
      )
      .eq("match_id", match.id);

    if (predFetchErr) {
      errors.push(`${match.id}: prediction fetch failed — ${predFetchErr.message}`);
      continue;
    }

    const powerupIds = [
      ...new Set(
        (predictions ?? [])
          .map((p) => p.applied_powerup_id as string | null)
          .filter((id): id is string => !!id),
      ),
    ];
    const powerupTypeById = new Map<string, PowerUpType>();
    if (powerupIds.length > 0) {
      const { data: chips } = await supabase
        .from("user_powerups")
        .select("id, powerup_type")
        .in("id", powerupIds);
      for (const chip of chips ?? []) {
        powerupTypeById.set(chip.id, chip.powerup_type as PowerUpType);
      }
    }

    const multiplier = existing.base_multiplier;
    const usersToEvaluate = new Set<string>();

    for (const pred of predictions ?? []) {
      const powerupType = pred.applied_powerup_id
        ? powerupTypeById.get(pred.applied_powerup_id) ?? null
        : null;
      const basePoints = calculateBasePoints(
        sport,
        pred.predicted_home_score,
        pred.predicted_away_score,
        match.actual_home_score,
        match.actual_away_score,
      );
      const powered = applyPowerUp(
        basePoints,
        powerupType,
        pred.predicted_home_score,
        pred.predicted_away_score,
        match.actual_home_score,
        match.actual_away_score,
      );
      const pointsWon = applyMultiplier(powered.points, multiplier);

      const { error: predUpdateErr } = await supabase
        .from("predictions")
        .update({
          points_won: pointsWon,
          is_banker_exact: powered.isBankerExact,
        })
        .eq("id", pred.id);

      if (predUpdateErr) {
        errors.push(`${pred.id}: prediction update failed — ${predUpdateErr.message}`);
        continue;
      }

      if (pred.applied_powerup_id) {
        await supabase
          .from("user_powerups")
          .update({
            status: "used",
            used_at: new Date().toISOString(),
            applied_fixture_id: match.id,
          })
          .eq("id", pred.applied_powerup_id)
          .eq("status", "available");
      }

      if (pred.user_id) usersToEvaluate.add(pred.user_id);
      predictionsGraded++;
    }

    for (const userId of usersToEvaluate) {
      await supabase.rpc("evaluate_powerup_unlocks", {
        p_user_id: userId,
        p_sport_type: sport,
        p_season_id: null,
      });
    }
  }

  if (errors.length > 0 && matchesSettled === 0) {
    return jsonResponse(
      { error: "Settlement failed.", detail: errors },
      500,
    );
  }

  const usage = await client.getUsageToday(sport as SharedSport).catch(() => null);
  client.logRunSummary({
    sport,
    date,
    fetched: fixtures.length,
    matchesSettled,
    predictionsGraded,
    callsMadeToday: usage?.calls_made ?? null,
    remainingBudget:
      usage != null ? Math.max(0, DAILY_BUDGET_CAP - usage.calls_made) : null,
  });

  return jsonResponse({
    sport,
    date,
    fetched: fixtures.length,
    completed: completed.length,
    matches_settled: matchesSettled,
    predictions_graded: predictionsGraded,
    callsThisRun: client.stats.callsThisRun,
    callsMadeToday: usage?.calls_made ?? null,
    budget: DAILY_BUDGET_CAP,
    ...(errors.length > 0 ? { warnings: errors } : {}),
  });
  } catch (err) {
    if (err instanceof UpstreamAuthError) {
      return jsonResponse(
        {
          error: "Upstream API-Sports authentication failure",
          status: err.status,
          caller: err.caller,
        },
        err.status,
      );
    }
    throw err;
  }
});

/**
 * Shared API-Sports client for Supabase Edge Functions (Deno).
 * Port of scripts/lib/apiSportsClient.ts — keep behaviour in sync.
 * Per-sport daily budget (football and rugby each get DAILY_BUDGET_CAP).
 */

import type { SupabaseClient } from "npm:@supabase/supabase-js@2";

export type Sport = "football" | "rugby";

/**
 * Soft safety margin under the verified Pro plan (~7500/day).
 * Override per deploy with API_SPORTS_DAILY_BUDGET if needed.
 */
export const DAILY_BUDGET_CAP = (() => {
  const raw = Deno.env.get("API_SPORTS_DAILY_BUDGET");
  const n = raw != null ? Number(raw) : NaN;
  return Number.isFinite(n) && n > 0 ? n : 7000;
})();

export const FOOTBALL_HOST = "https://v3.football.api-sports.io";
export const RUGBY_HOST = "https://v1.rugby.api-sports.io";

/** Thrown on upstream 401/403 — callers must halt the sync and not touch the DB. */
export class UpstreamAuthError extends Error {
  readonly status: number;
  readonly caller: string;

  constructor(status: number, caller: string) {
    super("Upstream API-Sports authentication failure");
    this.name = "UpstreamAuthError";
    this.status = status;
    this.caller = caller;
  }
}

export type ApiSportsResult =
  | {
      ok: true;
      status: number;
      json: any;
      rateLimit: { limit: number | null; remaining: number | null };
      callsMadeToday: number;
      remainingBudget: number;
    }
  | {
      ok: false;
      reason:
        | "budget_exhausted"
        | "network"
        | "http"
        | "plan_blocked"
        | "validation_error"
        | "auth_failure";
      message: string;
      callsMadeToday?: number;
      remainingBudget?: number;
      status?: number;
      json?: any;
    };

export type RunStats = {
  callsThisRun: number;
  skippedBudget: string[];
  skippedCache: string[];
  skippedNoNeed: string[];
  planBlocked: string[];
  validationErrors: string[];
};

export function createRunStats(): RunStats {
  return {
    callsThisRun: 0,
    skippedBudget: [],
    skippedCache: [],
    skippedNoNeed: [],
    planBlocked: [],
    validationErrors: [],
  };
}

/** Sole supported secret name for API-Sports credentials. */
export function getApiSportsKey(): string | null {
  const key = Deno.env.get("API_SPORTS_KEY");
  return typeof key === "string" && key.length > 0 ? key : null;
}

export function classifyApiErrors(
  errors: unknown,
): "none" | "plan_blocked" | "validation_error" {
  if (errors == null) return "none";
  if (Array.isArray(errors) && errors.length === 0) return "none";
  if (typeof errors === "object" && !Array.isArray(errors)) {
    if (Object.keys(errors as object).length === 0) return "none";
  }
  const msg = JSON.stringify(errors);
  if (
    /plan|subscription|upgrade|free plans do not have access|do not have access to this (date|season)/i.test(
      msg,
    )
  ) {
    return "plan_blocked";
  }
  return "validation_error";
}

export function resolveSeasonYear(
  now: Date = new Date(),
  opts: { maxSeason?: number; override?: number | null } = {},
): { season: number; preferred: number; clamped: boolean } {
  if (opts.override != null && Number.isFinite(opts.override)) {
    return {
      season: opts.override,
      preferred: opts.override,
      clamped: false,
    };
  }
  const y = now.getUTCFullYear();
  const m = now.getUTCMonth() + 1;
  const preferred = m >= 7 ? y : y - 1;
  const maxSeason = opts.maxSeason ?? y;
  const season = Math.min(preferred, maxSeason);
  return { season, preferred, clamped: season !== preferred };
}

export function utcDay(d = new Date()): string {
  return d.toISOString().slice(0, 10);
}

export function hostFor(sport: Sport): string {
  return sport === "football" ? FOOTBALL_HOST : RUGBY_HOST;
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

function readRateLimitRemaining(headers: Headers): number | null {
  const rem =
    headers.get("x-ratelimit-requests-remaining") ??
    headers.get("x-ratelimit-remaining");
  if (rem == null || rem === "") return null;
  const n = Number(rem);
  return Number.isFinite(n) ? n : null;
}

function readRateLimitLimit(headers: Headers): number | null {
  const lim =
    headers.get("x-ratelimit-requests-limit") ??
    headers.get("x-ratelimit-limit");
  if (lim == null || lim === "") return null;
  const n = Number(lim);
  return Number.isFinite(n) ? n : null;
}

export class RateLimiter {
  private lastAt = 0;
  remaining: number | null = null;
  limit: number | null = null;

  constructor(private minIntervalMs: number) {}

  noteHeaders(headers: Headers) {
    this.remaining = readRateLimitRemaining(headers);
    this.limit = readRateLimitLimit(headers);
    if (this.remaining != null) {
      console.log(
        `[api-sports] rate-limit remaining=${this.remaining}/${this.limit ?? "?"}`,
      );
      if (this.remaining < 500) {
        console.warn(
          `[api-sports] WARNING: rate-limit remaining below 500 (${this.remaining}/${this.limit ?? "?"})`,
        );
      }
    }
  }

  async waitTurn() {
    const now = Date.now();
    const wait = Math.max(0, this.lastAt + this.minIntervalMs - now);
    if (wait > 0) {
      console.log(`[api-sports] throttling ${wait}ms…`);
      await sleep(wait);
    }
    if (this.remaining != null && this.remaining <= 3) {
      console.warn("[api-sports] upstream remaining ≤3 — sleeping 60s");
      await sleep(60_000);
    }
    this.lastAt = Date.now();
  }
}

export type ApiSportsClientOptions = {
  supabase: SupabaseClient;
  apiKey: string;
  caller: string;
  budgetCap?: number;
  minIntervalMs?: number;
  stats?: RunStats;
};

export class ApiSportsClient {
  private limiter: RateLimiter;
  private budgetCap: number;
  readonly stats: RunStats;

  constructor(private opts: ApiSportsClientOptions) {
    this.budgetCap = opts.budgetCap ?? DAILY_BUDGET_CAP;
    this.limiter = new RateLimiter(opts.minIntervalMs ?? 7000);
    this.stats = opts.stats ?? createRunStats();
  }

  async getUsageToday(sport: Sport) {
    const { data, error } = await this.opts.supabase.rpc("get_api_quota_usage", {
      p_date: utcDay(),
      p_sport: sport,
    });
    if (error) throw error;
    return data as {
      date: string;
      sport: string;
      calls_made: number;
      last_remaining_from_header: number | null;
      last_limit_from_header: number | null;
    };
  }

  /** Strict post-fetch gate: 401/403 halt the entire sync. */
  private assertUpstreamAuth(res: Response): void {
    if (res.status === 401 || res.status === 403) {
      console.error(
        `[api-sports] CRITICAL: Upstream API-Sports authentication failure (HTTP ${res.status}, caller=${this.opts.caller})`,
      );
      throw new UpstreamAuthError(res.status, this.opts.caller);
    }
  }

  async get(
    sport: Sport,
    apiPath: string,
    params: Record<string, string | number> = {},
    skipLabel?: string,
  ): Promise<ApiSportsResult> {
    const day = utcDay();

    const { data: reserved, error: reserveErr } = await this.opts.supabase.rpc(
      "reserve_api_quota",
      {
        p_date: day,
        p_sport: sport,
        p_budget: this.budgetCap,
        p_caller: this.opts.caller,
      },
    );

    if (reserveErr) {
      return {
        ok: false,
        reason: "http",
        message: `reserve_api_quota failed: ${reserveErr.message}`,
      };
    }

    const reservation = reserved as {
      allowed: boolean;
      calls_made: number;
      remaining_budget: number;
      budget: number;
    };

    if (!reservation.allowed) {
      const label = skipLabel || `${sport} ${apiPath}`;
      this.stats.skippedBudget.push(label);
      console.warn(
        `[api-sports] BUDGET EXHAUSTED (${sport}) — skipped ${label} (calls_made=${reservation.calls_made}/${this.budgetCap})`,
      );
      return {
        ok: false,
        reason: "budget_exhausted",
        message: `Daily ${sport} budget ${this.budgetCap} exhausted`,
        callsMadeToday: reservation.calls_made,
        remainingBudget: 0,
      };
    }

    await this.limiter.waitTurn();

    const url = new URL(apiPath, hostFor(sport));
    for (const [k, v] of Object.entries(params)) {
      url.searchParams.set(k, String(v));
    }

    const fetchHeaders = {
      "x-apisports-key": this.opts.apiKey,
      Accept: "application/json",
      "Cache-Control": "no-cache",
      Pragma: "no-cache",
    };

    console.log(
      `[api-sports] GET ${url.pathname}?${url.searchParams} (caller=${this.opts.caller}, sport=${sport}, #${reservation.calls_made}/${this.budgetCap})`,
    );

    let res: Response;
    try {
      res = await fetch(url.toString(), {
        headers: fetchHeaders,
        cache: "no-store",
      });
    } catch (err) {
      return {
        ok: false,
        reason: "network",
        message: err instanceof Error ? err.message : String(err),
        callsMadeToday: reservation.calls_made,
        remainingBudget: reservation.remaining_budget,
      };
    }

    this.limiter.noteHeaders(res.headers);
    this.stats.callsThisRun += 1;
    this.assertUpstreamAuth(res);

    await this.opts.supabase.rpc("record_api_quota_headers", {
      p_date: day,
      p_sport: sport,
      p_remaining: this.limiter.remaining,
      p_limit: this.limiter.limit,
    });

    if (res.status === 429) {
      console.warn("[api-sports] 429 — backing off 65s then retrying once");
      await sleep(65_000);
      const retry = await fetch(url.toString(), {
        headers: fetchHeaders,
        cache: "no-store",
      });
      this.limiter.noteHeaders(retry.headers);
      this.assertUpstreamAuth(retry);
      const retryJson = await retry.json().catch(() => ({}));
      return this.wrapOk(retry, retryJson, reservation);
    }

    const json = await res.json().catch(() => ({}));
    if (!res.ok) {
      return {
        ok: false,
        reason: "http",
        message: `HTTP ${res.status}`,
        status: res.status,
        json,
        callsMadeToday: reservation.calls_made,
        remainingBudget: reservation.remaining_budget,
      };
    }

    return this.wrapOk(res, json, reservation);
  }

  private wrapOk(
    res: Response,
    json: any,
    reservation: { calls_made: number; remaining_budget: number },
  ): ApiSportsResult {
    const kind = classifyApiErrors(json?.errors);
    if (kind === "plan_blocked") {
      const msg = JSON.stringify(json.errors);
      console.error(`[api-sports] PLAN BLOCKED: ${msg}`);
      this.stats.planBlocked.push(msg);
      return {
        ok: false,
        reason: "plan_blocked",
        message: msg,
        status: res.status,
        json,
        callsMadeToday: reservation.calls_made,
        remainingBudget: reservation.remaining_budget,
      };
    }
    if (kind === "validation_error") {
      const msg = JSON.stringify(json.errors);
      console.error(
        `[api-sports] VALIDATION ERROR (malformed request — aborting this call path): ${msg}`,
      );
      this.stats.validationErrors.push(msg);
      return {
        ok: false,
        reason: "validation_error",
        message: msg,
        status: res.status,
        json,
        callsMadeToday: reservation.calls_made,
        remainingBudget: reservation.remaining_budget,
      };
    }

    return {
      ok: true,
      status: res.status,
      json,
      rateLimit: {
        limit: this.limiter.limit,
        remaining: this.limiter.remaining,
      },
      callsMadeToday: reservation.calls_made,
      remainingBudget: reservation.remaining_budget,
    };
  }

  logRunSummary(extra: Record<string, unknown> = {}) {
    console.log(
      JSON.stringify({
        tag: "api-sports-run-summary",
        caller: this.opts.caller,
        budgetCap: this.budgetCap,
        callsThisRun: this.stats.callsThisRun,
        skippedBudget: this.stats.skippedBudget,
        skippedCache: this.stats.skippedCache,
        skippedNoNeed: this.stats.skippedNoNeed,
        planBlocked: this.stats.planBlocked,
        validationErrors: this.stats.validationErrors,
        ...extra,
      }),
    );
  }

  /** Latest upstream rate-limit remaining observed this client instance. */
  get lastRemaining(): number | null {
    return this.limiter.remaining;
  }
}

export type SystemMetricStatus = "STABLE" | "ERROR";

/**
 * Upsert a health row for the Admin API Status widget.
 * Failures are logged but never throw — metrics must not break sync.
 */
export async function reportSystemMetric(
  supabase: SupabaseClient,
  opts: {
    serviceName: string;
    status: SystemMetricStatus;
    apiQuotaRemaining?: number | null;
    errorMessage?: string | null;
  },
): Promise<void> {
  try {
    const { error } = await supabase.from("system_metrics").upsert(
      {
        service_name: opts.serviceName,
        status: opts.status,
        last_sync_time: new Date().toISOString(),
        api_quota_remaining: opts.apiQuotaRemaining ?? null,
        error_message: opts.status === "ERROR"
          ? (opts.errorMessage ?? "Unknown error")
          : null,
        updated_at: new Date().toISOString(),
      },
      { onConflict: "service_name" },
    );
    if (error) {
      console.warn(`[system_metrics] upsert failed: ${error.message}`);
    }
  } catch (err) {
    console.warn(
      `[system_metrics] upsert threw: ${
        err instanceof Error ? err.message : String(err)
      }`,
    );
  }
}

/**
 * Canonical football league catalog for Edge sync functions.
 * Keep in sync with src/constants/competitions.ts FOOTBALL_LEAGUE_META.
 */

export type FootballLeagueDef = {
  slug: string;
  apiId: number;
  title: string;
};

export const FOOTBALL_LEAGUES: readonly FootballLeagueDef[] = [
  { slug: "f-epl", apiId: 39, title: "English Premier League" },
  { slug: "f-spfl", apiId: 179, title: "Scottish Premiership" },
  { slug: "f-championship", apiId: 40, title: "EFL Championship" },
  { slug: "f-ucl", apiId: 2, title: "UEFA Champions League" },
  { slug: "f-uel", apiId: 3, title: "UEFA Europa League" },
  { slug: "f-shield", apiId: 528, title: "FA Community Shield" },
  { slug: "f-facup", apiId: 45, title: "FA Cup" },
  { slug: "f-worldcup", apiId: 1, title: "FIFA World Cup" },
  { slug: "f-laliga", apiId: 140, title: "La Liga" },
  { slug: "f-bundesliga", apiId: 78, title: "Bundesliga" },
  { slug: "f-ligue1", apiId: 61, title: "Ligue 1" },
] as const;

/** Legacy API id that previously mapped Community Shield incorrectly. */
const LEGACY_SHIELD_API_ID = 52;

export const FOOTBALL_API_IDS: ReadonlySet<number> = new Set([
  ...FOOTBALL_LEAGUES.map((l) => l.apiId),
  LEGACY_SHIELD_API_ID,
]);

export const FOOTBALL_SLUG_BY_API: Record<string, string> = {
  ...Object.fromEntries(
    FOOTBALL_LEAGUES.map((l) => [`football:${l.apiId}`, l.slug]),
  ),
  [`football:${LEGACY_SHIELD_API_ID}`]: "f-shield",
};

export const FOOTBALL_TITLE_BY_SLUG: Record<string, string> = Object.fromEntries(
  FOOTBALL_LEAGUES.map((l) => [l.slug, l.title]),
);

export function footballSlugForApiId(apiId: unknown): string | null {
  if (apiId == null) return null;
  const n = Number(apiId);
  if (!Number.isFinite(n)) return null;
  return FOOTBALL_SLUG_BY_API[`football:${n}`] || `football-${n}`;
}

export function footballTitleForSlug(
  slug: string | null,
  apiName?: string | null,
): string | null {
  if (slug && FOOTBALL_TITLE_BY_SLUG[slug]) return FOOTBALL_TITLE_BY_SLUG[slug];
  return apiName ?? null;
}
